void fom_set_default_settings(FomSettings *settings) {
    settings->max_iter = FOM_MAX_ITER;
    settings->tol = FOM_TOL;
    settings->check_termination = FOM_CHECK_TERMINATION;
}

void fom_setup(FomWorkspace *work, const FomSettings *settings) {
    work->settings = *settings;
    memcpy(work->state, FOM_STATE_INIT, sizeof(work->state));
}

void fom_update_params(FomWorkspace *work, const FomParams *params) {
    work->params = *params;
    memcpy(work->state, FOM_STATE_INIT, sizeof(work->state));
}

fom_int fom_solve(FomWorkspace *work) {
    fom_float *state = work->state;
    fom_float *ns = work->new_state;
    const fom_int max_iter = work->settings.max_iter;
    const fom_int use_tol = FOM_USE_TOL && work->settings.check_termination;
    const fom_float tol = work->settings.tol;
    fom_float res = 0;
    fom_int it, i, j;

    /* Parameter contribution to the state update is loop-invariant; cache it
       in solution.x, which is only written with the result after the loop. */
    fom_float *pterm = work->solution.x;
    memset(pterm, 0, sizeof(fom_float) * FOM_STATE_DIM);
    fom_apply_su_p_p0(work->params.p0, pterm);

    for (it = 0; it < max_iter; ++it) {
        const fom_float xi = fom_sched_xi(it);

        FOM_PROF_BEGIN(fused_pass);
        {
            const fom_float *restrict x = state;
            const fom_float *restrict s1 = state + 600;
            const fom_float *restrict s2 = state + 620;
            fom_float *restrict o_ns = ns;
            fom_float *restrict lane = work->acc; /* 600 per-(j,k) t1 partials */
            fom_float aB[30];
            for (i = 0; i < 30; ++i) aB[i] = (SUF_B[i] + xi * SUF_D[i]) * s2[i];
            for (j = 0; j < 20; ++j) {
                const fom_int o = 30 * j;
                const fom_float s1j = s1[j];
                fom_float *restrict lB = lane + o; /* per-lane t1 partials: keeps k-loop vectorizable */
                fom_int k;
                for (k = 0; k < 30; ++k) {
                    const fom_int q = o + k;
                    const fom_float xv = x[q];
                    fom_float v = FOM_MAT_t0_c[q] + (xv + T0_A[q] * s1j + T0_B[q] * s2[k]);
                    v = v < FOM_MAT_t0_lo[q] ? FOM_MAT_t0_lo[q] : v;
                    v = v > FOM_MAT_t0_hi[q] ? FOM_MAT_t0_hi[q] : v;
                    o_ns[q] = v; /* su_t_t0 = I and pterm = 0 on rows 0..599 */
                    lB[k] = (T1S_B[q] * xv + T1T_B[q] * v)
                          + xi * (T1S_D[q] * xv + T1T_D[q] * v);
                    aB[k] += (SUS_B[q] * xv + SUT_B[q] * v)
                           + xi * (SUS_D[q] * xv + SUT_D[q] * v);
                }
            }
            FOM_PROF_END(fused_pass);
            FOM_PROF_BEGIN(t1_reduce);
            /* t1 reductions: k outer, j inner, so the 20 independent row sums
               run in parallel lanes instead of one serial add chain. */
            {
                fom_float tb[20];
                for (j = 0; j < 20; ++j) tb[j] = (T1L_B[j] + xi * T1L_D[j]) * s1[j];
                for (i = 0; i < 30; ++i)
                    for (j = 0; j < 20; ++j) tb[j] += lane[30 * j + i];
                for (j = 0; j < 20; ++j) {
                    const fom_float v = FOM_MAT_t1_c[j] + tb[j];
                    o_ns[600 + j] = v > 0 ? v : 0; /* su_t_t1 = I, pterm = 0 */
                }
            }
            for (i = 0; i < 30; ++i) o_ns[620 + i] = pterm[620 + i] + aB[i];
            FOM_PROF_END(t1_reduce);
        }
        FOM_PROF_BEGIN(residual);
        /* residual only needed for the tolerance test or the final report */
        if (use_tol || it + 1 == max_iter) {
            res = 0;
            for (i = 0; i < FOM_STATE_DIM; ++i) {
                fom_float d = ns[i] - state[i];
                d = d < 0 ? -d : d;
                res = d > res ? d : res;
            }
        }
        /* swap buffers instead of copying */
        { fom_float *tmp = state; state = ns; ns = tmp; }
        FOM_PROF_END(residual);

        if (use_tol && res <= tol) {
            ++it;
            work->solution.iter = it;
            work->solution.residual = res;
            work->solution.status = FOM_SOLVED;
            memcpy(work->solution.x, state, sizeof(work->solution.x));
            if (state != work->state) memcpy(work->state, state, sizeof(work->state));
            return FOM_SOLVED;
        }
    }

    work->solution.iter = it;
    work->solution.residual = res;
    work->solution.status = FOM_MAX_ITER_REACHED;
    memcpy(work->solution.x, state, sizeof(work->solution.x));
    if (state != work->state) memcpy(work->state, state, sizeof(work->state));
    return FOM_MAX_ITER_REACHED;
}

void fom_cleanup(FomWorkspace *work) {
    (void)work;
}
